const m = $json.message || {};
const photos = m.photo || [];
const best = photos[photos.length - 1];
return [{ json: { file_id: best.file_id, chat_id: m.chat.id } }];

const raw = (($json.message || {}).content) || '';
const chat_id = $('Выбрать фото').first().json.chat_id;
let d = null;
try { d = JSON.parse(raw); } catch (e) { d = null; }
if (!d) { return [{ json: { status: 'retry', reason: 'ответ модели не разобрался', chat_id } }]; }
const items = Array.isArray(d.items) ? d.items : [];
const itemsSum = Math.round(items.reduce((a, it) => a + (Number(it.sum) || 0), 0) * 100) / 100;
const total = Math.round((Number(d.total) || 0) * 100) / 100;
const filled = Boolean(d.seller) && Boolean(d.date) && total > 0 && items.length > 0;
const matches = Math.abs(itemsSum - total) < 0.015;
const status = filled && matches ? 'ok' : 'retry';
const reason = !filled ? 'часть полей не прочиталась' : (!matches ? 'сумма позиций не равна итогу' : '');
return [{ json: { status, reason, chat_id, seller: d.seller || '', inn: d.inn || '', date: d.date || '', total, items_sum: itemsSum, items_count: items.length, items } }];

const data = $getWorkflowStaticData('global');
data.rows = data.rows || [];
const q = (v) => '"' + String(v).replace(/"/g, '""') + '"';
data.rows.push([$json.date, $json.seller, $json.inn, $json.total.toFixed(2), $json.items_count].map(q).join(';'));
const csv = '\uFEFF' + ['"Дата";"Продавец";"ИНН";"Итого";"Позиций"'].concat(data.rows).join('\n');
return [{ json: { chat_id: $json.chat_id, seller: $json.seller, inn: $json.inn, date: $json.date, total: $json.total, items_count: $json.items_count, csv, rows_total: data.rows.length } }];

